	if err != nil {
		return err
	}
	if err := brainstore.WriteBrainRelativeFileAtomic(brainDir, RepositoryPath, append(data, '\n'), 0o600); err != nil {
		return err
	}
	return cleanupRepoFactTemps(brainDir)
}

