package cli

// Audit probes, not an index implementation. These pin effective source
// revisions an eventual derived cache would have to cover.
import (
 "bytes"
 "crypto/sha256"
 "encoding/json"
 "os"
 "path/filepath"
 "testing"
 "time"

 "github.com/entireio/entire-brain/factmerge"
 "github.com/entireio/entire-brain/internal/cli/internal/factstore"
)

func TestENH004SameStatDifferentSource(t *testing.T) {
 t.Parallel()
 dir:=t.TempDir()
 record:=factmerge.Record{ID:"revision-probe",Text:"alpha",Status:factmerge.StatusActive,Origin:"authored",CreatedAt:time.Unix(1,0).UTC(),UpdatedAt:time.Unix(1,0).UTC()}
 if err:=factstore.Write(dir,[]factmerge.Record{record});err!=nil {t.Fatal(err)}
 path:=filepath.Join(dir,factstore.RepositoryPath)
 old,err:=os.ReadFile(path);if err!=nil {t.Fatal(err)}
 before,err:=os.Stat(path);if err!=nil {t.Fatal(err)}
 changed:=bytes.Replace(old,[]byte(`"alpha"`),[]byte(`"omega"`),1)
 if bytes.Equal(old,changed)||len(old)!=len(changed) {t.Fatal("invalid same-size mutation")}
 // Deliberate external/older writer in an isolated test tree.
 if err:=os.WriteFile(path,changed,0o600);err!=nil {t.Fatal(err)}
 if err:=os.Chtimes(path,before.ModTime(),before.ModTime());err!=nil {t.Fatal(err)}
 after,err:=os.Stat(path);if err!=nil {t.Fatal(err)}
 if before.Size()!=after.Size()||!before.ModTime().Equal(after.ModTime()) {t.Fatal("stat signature changed")}
 if sha256.Sum256(old)==sha256.Sum256(changed) {t.Fatal("digest failed to distinguish mutation")}
 loaded,err:=factstore.Load(dir);if err!=nil {t.Fatal(err)}
 if len(loaded)!=1||loaded[0].Text!="omega" {t.Fatalf("canonical reader did not observe new bytes: %+v",loaded)}
}

func TestENH004CanonicalDigestMissesLegacySource(t *testing.T) {
 t.Parallel()
 dir:=t.TempDir()
 record:=factmerge.Record{ID:"canonical",Text:"canonical record",Status:factmerge.StatusActive,Origin:"authored",CreatedAt:time.Unix(1,0).UTC(),UpdatedAt:time.Unix(1,0).UTC()}
 if err:=factstore.Write(dir,[]factmerge.Record{record});err!=nil {t.Fatal(err)}
 canonical:=filepath.Join(dir,factstore.RepositoryPath)
 before,err:=os.ReadFile(canonical);if err!=nil {t.Fatal(err)}
 legacyDir:=filepath.Join(dir,"facts","released-writer")
 if err:=os.MkdirAll(legacyDir,0o700);err!=nil {t.Fatal(err)}
 legacy:=record;legacy.ID="legacy";legacy.Text="later released-client record"
 data,err:=json.Marshal(legacy);if err!=nil {t.Fatal(err)}
 if err:=os.WriteFile(filepath.Join(legacyDir,"facts.ndjson"),append(data,'\n'),0o600);err!=nil {t.Fatal(err)}
 after,err:=os.ReadFile(canonical);if err!=nil {t.Fatal(err)}
 if !bytes.Equal(before,after) {t.Fatal("flat-store bytes changed")}
 loaded,err:=factstore.Load(dir);if err!=nil {t.Fatal(err)}
 found:=false;for _,r:=range loaded {if r.ID==legacy.ID&&r.Text==legacy.Text {found=true}}
 if len(loaded)!=2||!found {t.Fatalf("effective source revision missed legacy write: %+v",loaded)}
}
