package cli

// Isolated ENH-004 research only. No production source changes or canonical
// writes. Every process freshly loads authoritative facts before optional reuse.
import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math"
	"net/url"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/entireio/entire-brain/internal/cli/internal/base"
	"github.com/entireio/entire-brain/internal/cli/internal/factstore"
	"github.com/entireio/entire-brain/internal/cli/internal/retrieval"
	"github.com/entireio/entire-brain/internal/cli/internal/sqlitedriver"
)

const enh004ProbeRevision = "ENH004-probe-schema1-tokenizer1-scorer1"

type enh004ProbeDoc struct {
	length int
	locus  []string
}
type enh004ProbeIndex struct {
	db     *sql.DB
	path   string
	reused bool
	build  time.Duration
}

func enh004ProbeDigest(facts []factRecord, scope string) (string, error) {
	h := sha256.New()
	if _, err := fmt.Fprintln(h, enh004ProbeRevision, scope); err != nil {
		return "", err
	}
	enc := json.NewEncoder(h)
	// Load returns deterministic full record order; all decoded fields participate.
	for i := range facts {
		if err := enc.Encode(facts[i]); err != nil {
			return "", err
		}
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

func enh004ProbeOpen(ctx context.Context, path, digest string, count int) (*sql.DB, error) {
	u := url.URL{Scheme: "file", Path: path}
	q := u.Query()
	q.Set("mode", "ro")
	u.RawQuery = q.Encode()
	db, err := sql.Open(sqlitedriver.Name, u.String())
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(1)
	var got string
	var n int
	if err = db.QueryRowContext(ctx, `SELECT digest,documents FROM meta WHERE revision=?`, enh004ProbeRevision).Scan(&got, &n); err != nil {
		_ = db.Close()
		return nil, err
	}
	if got != digest || n != count {
		_ = db.Close()
		return nil, fmt.Errorf("invalid prepared snapshot metadata")
	}
	return db, nil
}

func enh004ProbePrepare(ctx context.Context, cache, digest string, facts []factRecord) (enh004ProbeIndex, error) {
	path := filepath.Join(cache, digest+".sqlite")
	if _, err := os.Stat(path); err == nil {
		db, e := enh004ProbeOpen(ctx, path, digest, len(facts))
		return enh004ProbeIndex{db: db, path: path, reused: true}, e
	} else if !os.IsNotExist(err) {
		return enh004ProbeIndex{}, err
	}
	start := time.Now()
	if err := os.MkdirAll(cache, 0700); err != nil {
