const (
	factIndexSchemaVersion             = 1
	factIndexTokenizerVersion          = 1
	factIndexLocusVersion              = 1
	factIndexScorerVersion             = 1
	factIndexMaxBytes            int64 = 64 << 20
	factIndexMaxDocuments              = 100000
	factIndexDescriptorMaxBytes  int64 = 4096
	factIndexMaxDirectoryEntries       = 32
	factIndexNamespace                 = "fact-lexical-v1"
	factIndexLockName                  = "write.lock"
	factIndexPublishPrefix             = ".publish-"
)

var (
	errFactIndexUnsafe = errors.New("unsafe fact index cache")
	errFactIndexBudget = errors.New("fact index cache budget exceeded")
)

type factIndexDocument struct {
	Signature string
	Length    int
	// Even nil is the computed effective locus. Readers never derive it again.
	Locus []string
}

type factIndexPosting struct {
	Document  int
	Frequency int
}

type factPreparedIndex struct {
	docs       []factIndexDocument
	reused     bool
	db         *sql.DB
	privateDir string
	generation string
}

type factIndexRevision struct {
	Schema    int `json:"schema"`
	Tokenizer int `json:"tokenizer"`
	Locus     int `json:"locus"`
	Scorer    int `json:"scorer"`
}

type factIndexDescriptor struct {
	Revision  factIndexRevision `json:"revision"`
	Source    string            `json:"source"`
	Documents int               `json:"documents"`
	Size      int64             `json:"size"`
	SHA256    string            `json:"sha256"`
	CreatedAt time.Time         `json:"created_at"`
}

func currentFactIndexRevision() factIndexRevision {
	return factIndexRevision{factIndexSchemaVersion, factIndexTokenizerVersion, factIndexLocusVersion, factIndexScorerVersion}
}

func factIndexRecordSignature(record factRecord) (string, error) {
	data, err := json.Marshal(record)
	if err != nil {
		return "", fmt.Errorf("encode fact index record: %w", err)
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

func factIndexSourceRevision(ctx context.Context, scope string, source []factRecord) (string, []string, error) {
	if len(source) > factIndexMaxDocuments {
		return "", nil, errFactIndexBudget
	}
	h := sha256.New()
	header := struct {
		Revision   factIndexRevision
		Scope      string
		Projection string
	}{currentFactIndexRevision(), scope, "factstore-effective-record-v3"}
	if err := json.NewEncoder(h).Encode(header); err != nil {
		return "", nil, fmt.Errorf("encode fact index revision: %w", err)
	}
	signatures := make([]string, len(source))
	for i := range source {
		if err := ctx.Err(); err != nil {
			return "", nil, err
		}
		data, err := json.Marshal(source[i])
		if err != nil {
			return "", nil, fmt.Errorf("encode fact index source: %w", err)
		}
		sum := sha256.Sum256(data)
		signatures[i] = hex.EncodeToString(sum[:])
		_, _ = h.Write(data)
		_, _ = h.Write([]byte{'\n'})
	}
	return hex.EncodeToString(h.Sum(nil)), signatures, nil
}

func factIndexDirectory(env base.EntireEnv, scope string) (string, error) {
	if strings.TrimSpace(scope) == "" {
		return "", fmt.Errorf("fact index requires a source identity")
	}
	dirs, err := base.ResolvePluginDirs(env)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256([]byte(scope))
	return filepath.Join(dirs.Cache, factIndexNamespace, hex.EncodeToString(sum[:])), nil
}

// The cache root is resolved by PluginDirs, not derived from an artifact path.
// All descendants are pinned and refuse links before any reads or mutations.
type factIndexPinnedDirectory struct {
	cachePath     string
	cache         *os.Root
	cacheInfo     os.FileInfo
	namespace     *os.Root
	namespaceInfo os.FileInfo
	scope         *os.Root
	scopeInfo     os.FileInfo
	scopeName     string
}

func factIndexOpenDirectoryPath(path string) (*os.Root, os.FileInfo, error) {
	info, err := os.Lstat(path)
	if os.IsNotExist(err) {
		parentPath := filepath.Dir(path)
		if parentPath == path {
			return nil, nil, err
		}
		parent, _, openErr := factIndexOpenDirectoryPath(parentPath)
		if openErr != nil {
			return nil, nil, openErr
		}
		defer parent.Close()
		name := filepath.Base(path)
		if mkdirErr := parent.Mkdir(name, 0700); mkdirErr != nil && !os.IsExist(mkdirErr) {
			return nil, nil, mkdirErr
		}
		return factIndexOpenChild(parent, name)
	}
	if err != nil {
		return nil, nil, err
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return nil, nil, fmt.Errorf("%w: cache root is not a directory", errFactIndexUnsafe)
	}
	root, err := os.OpenRoot(path)
	if err != nil {
		return nil, nil, err
	}
	opened, err := root.Stat(".")
	if err != nil || !os.SameFile(info, opened) {
		_ = root.Close()
		return nil, nil, fmt.Errorf("%w: cache root changed while opening", errFactIndexUnsafe)
	}
	return root, info, nil
}

func factIndexOpenChild(parent *os.Root, name string) (*os.Root, os.FileInfo, error) {
	info, err := parent.Lstat(name)
	if err != nil {
		return nil, nil, err
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return nil, nil, fmt.Errorf("%w: cache component is not a directory", errFactIndexUnsafe)
	}
	child, err := parent.OpenRoot(name)
	if err != nil {
		return nil, nil, err
	}
	opened, err := child.Stat(".")
	current, currentErr := parent.Lstat(name)
	if err != nil || currentErr != nil || current.Mode()&os.ModeSymlink != 0 || !os.SameFile(info, opened) || !os.SameFile(info, current) {
		_ = child.Close()
		return nil, nil, fmt.Errorf("%w: cache component changed while opening", errFactIndexUnsafe)
	}
	return child, info, nil
}

func openFactIndexPinnedDirectory(env base.EntireEnv, scope string) (*factIndexPinnedDirectory, error) {
	dirs, err := base.ResolvePluginDirs(env)
	if err != nil {
		return nil, err
	}
	path, err := factIndexDirectory(env, scope)
	if err != nil {
		return nil, err
	}
	pinned := &factIndexPinnedDirectory{cachePath: dirs.Cache, scopeName: filepath.Base(path)}
	pinned.cache, pinned.cacheInfo, err = factIndexOpenDirectoryPath(dirs.Cache)
	if err != nil {
		return nil, err
	}
	fail := func(e error) (*factIndexPinnedDirectory, error) { pinned.Close(); return nil, e }
	if err = pinned.cache.Mkdir(factIndexNamespace, 0700); err != nil && !os.IsExist(err) {
		return fail(err)
	}
	pinned.namespace, pinned.namespaceInfo, err = factIndexOpenChild(pinned.cache, factIndexNamespace)
	if err != nil {
		return fail(err)
	}
	if err = pinned.namespace.Mkdir(pinned.scopeName, 0700); err != nil && !os.IsExist(err) {
		return fail(err)
	}
	pinned.scope, pinned.scopeInfo, err = factIndexOpenChild(pinned.namespace, pinned.scopeName)

