func insertFactIndexDocuments(ctx context.Context, tx *sql.Tx, source []factRecord, signatures []string) error {
	docs, err := tx.PrepareContext(ctx, `INSERT INTO fact_index_documents VALUES(?,?,?,?)`)
	if err != nil {
		return err
	}
	defer docs.Close()
	postings, err := tx.PrepareContext(ctx, `INSERT INTO fact_index_postings VALUES(?,?,?)`)
	if err != nil {
		return err
	}
	defer postings.Close()
	for i := range source {
		if err = ctx.Err(); err != nil {
			return err
		}
		tokens := factSearchTokens(source[i])
		locus, marshalErr := json.Marshal(base.FactLocusOf(source[i]))
		if marshalErr != nil {
			return marshalErr
		}
		if _, err = docs.ExecContext(ctx, i, signatures[i], len(tokens), string(locus)); err != nil {
			return err
		}
		counts := make(map[string]int, len(tokens))
		for _, token := range tokens {
			counts[token]++
		}
		for token, n := range counts {
			if _, err = postings.ExecContext(ctx, token, i, n); err != nil {
				return err
			}
		}
	}
	return nil
}

func factIndexRandomName(suffix string) (string, error) {
	var data [16]byte
	if _, err := rand.Read(data[:]); err != nil {
		return "", err
	}
	return factIndexPublishPrefix + hex.EncodeToString(data[:]) + suffix, nil
}

func createFactIndexPublicationLeaf(root *os.Root, suffix string) (*os.File, string, error) {
	name, err := factIndexRandomName(suffix)
	if err != nil {
		return nil, "", err
	}
	f, err := root.OpenFile(name, os.O_CREATE|os.O_EXCL|os.O_WRONLY|base.FileLockOpenFlags(), 0600)
	if err != nil {
		return nil, "", err
	}
	return f, name, nil
}

func publishFactIndexDatabase(ctx context.Context, p *factIndexPinnedDirectory, staging, digest string, count int) error {
	source, err := os.Open(staging)
	if err != nil {
		return err
	}
	defer source.Close()
	target, tempName, err := createFactIndexPublicationLeaf(p.scope, ".sqlite")
	if err != nil {
		return err
	}
	defer func() { _ = target.Close(); _ = p.scope.Remove(tempName) }()
	h := sha256.New()
	n, err := io.CopyBuffer(io.MultiWriter(target, h), io.LimitReader(&factIndexContextReader{ctx: ctx, reader: source}, factIndexMaxBytes+1), make([]byte, 64<<10))
	if err != nil {
		return err
	}
	if n < 1 || n > factIndexMaxBytes {
		return errFactIndexBudget
	}
	if err = target.Sync(); err != nil {
		return err
	}
	if err = target.Close(); err != nil {
		return err
	}
	if err = p.validate(); err != nil {
		return err
	}
	// Verify an old committed generation before pruning to one. A failed new
	// publication then still retains a complete, byte-verified old generation.
	if err = retainFactIndexGenerations(ctx, p, digest, 1); err != nil {
		return err
	}
	if err = replaceFactIndexLeaf(p, tempName, digest+".sqlite"); err != nil {
		return err
	}
	if err = brainstore.SyncPinnedDirectory(p.scope); err != nil {
		return err
	}
	descriptor := factIndexDescriptor{Revision: currentFactIndexRevision(), Source: digest, Documents: count, Size: n, SHA256: hex.EncodeToString(h.Sum(nil)), CreatedAt: time.Now().UTC()}
	data, err := json.Marshal(descriptor)
	if err != nil {
		return err
	}
	marker, markerName, err := createFactIndexPublicationLeaf(p.scope, ".json")
	if err != nil {
		return err
	}
	defer func() { _ = marker.Close(); _ = p.scope.Remove(markerName) }()
	if _, err = marker.Write(append(data, '\n')); err != nil {
		return err
	}
	if err = marker.Sync(); err != nil {
		return err
	}
	if err = marker.Close(); err != nil {
		return err
	}
	if err = ctx.Err(); err != nil {
		return err
	}
	// The descriptor is the commit record and is always published last.
	if err = replaceFactIndexLeaf(p, markerName, digest+".json"); err != nil {
		return err
	}
	if err = brainstore.SyncPinnedDirectory(p.scope); err != nil {
		return err
	}
	return p.validate()
}

func replaceFactIndexLeaf(p *factIndexPinnedDirectory, from, to string) error {
	if err := p.validate(); err != nil {
		return err
	}
	info, err := p.scope.Lstat(to)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	if err == nil && (info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular()) {
		return fmt.Errorf("%w: publication target is not a regular file", errFactIndexUnsafe)
	}
	return p.scope.Rename(from, to)
}

func factIndexDirectoryEntries(p *factIndexPinnedDirectory) ([]os.DirEntry, error) {
	f, err := p.scope.Open(".")
	if err != nil {
		return nil, err
	}
	defer f.Close()
	entries, err := f.ReadDir(factIndexMaxDirectoryEntries + 1)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, err
	}
	if len(entries) > factIndexMaxDirectoryEntries {
		return nil, errFactIndexBudget
	}
	return entries, p.validate()
}

func factIndexGenerationName(name, suffix string) (string, bool) {
	if !strings.HasSuffix(name, suffix) {
		return "", false
	}
	digest := strings.TrimSuffix(name, suffix)
	return digest, factIndexHexDigest(digest)
}

func removeFactIndexLeaf(p *factIndexPinnedDirectory, name string) error {
	info, err := p.scope.Lstat(name)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return err
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return fmt.Errorf("%w: cleanup target is not a regular file", errFactIndexUnsafe)
	}
	if err = p.validate(); err != nil {
		return err
	}
	return p.scope.Remove(name)
}

func factIndexPublicationName(name string) bool {
	if !strings.HasPrefix(name, factIndexPublishPrefix) {
		return false
	}
	body := strings.TrimPrefix(name, factIndexPublishPrefix)
	if strings.HasSuffix(body, ".sqlite") {
		body = strings.TrimSuffix(body, ".sqlite")
	} else if strings.HasSuffix(body, ".json") {
		body = strings.TrimSuffix(body, ".json")
	} else {
		return false
	}
	data, err := hex.DecodeString(body)
	return err == nil && len(data) == 16 && strings.ToLower(body) == body
}

func cleanupFactIndexOrphans(ctx context.Context, p *factIndexPinnedDirectory) error {
	entries, err := factIndexDirectoryEntries(p)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if err = ctx.Err(); err != nil {
			return err
		}
		name := entry.Name()
		if factIndexPublicationName(name) {
			if err = removeFactIndexLeaf(p, name); err != nil {
				return err
			}
			continue
		}
		digest, ok := factIndexGenerationName(name, ".sqlite")
		if !ok {
			continue
		}
		_, err = p.scope.Lstat(digest + ".json")
		if os.IsNotExist(err) {
			if err = removeFactIndexLeaf(p, name); err != nil {
				return err
			}
		} else if err != nil {
			return err
		}
	}
	return nil
}

func verifyFactIndexGeneration(ctx context.Context, p *factIndexPinnedDirectory, descriptor factIndexDescriptor) error {
	name := descriptor.Source + ".sqlite"
	f, info, err := factIndexOpenLeaf(p.scope, name, factIndexMaxBytes)
	if err != nil {
		return err
	}
	defer f.Close()
	h := sha256.New()
	n, err := io.CopyBuffer(h, io.LimitReader(&factIndexContextReader{ctx: ctx, reader: f}, factIndexMaxBytes+1), make([]byte, 64<<10))
	if err != nil {
		return err
	}
	if n != descriptor.Size || hex.EncodeToString(h.Sum(nil)) != descriptor.SHA256 {
		return fmt.Errorf("fact index retention candidate failed its digest")
	}
	return factIndexLeafUnchanged(p.scope, name, f, info)
}

func retainFactIndexGenerations(ctx context.Context, p *factIndexPinnedDirectory, replacing string, keep int) error {
	entries, err := factIndexDirectoryEntries(p)
	if err != nil {
		return err
	}
	type candidate struct {
		digest     string
		descriptor factIndexDescriptor
		valid      bool
	}
	generations := make([]candidate, 0, 2)
	for _, entry := range entries {
		digest, ok := factIndexGenerationName(entry.Name(), ".json")
		if !ok || digest == replacing {
			continue
		}
		descriptor, readErr := readFactIndexDescriptor(ctx, p, digest)
		if errors.Is(readErr, errFactIndexUnsafe) {
			return readErr
		}
		generations = append(generations, candidate{digest: digest, descriptor: descriptor, valid: readErr == nil})
	}
	if len(generations) > 4 {
		return errFactIndexBudget
	}
	sort.Slice(generations, func(i, j int) bool {
		return generations[i].descriptor.CreatedAt.After(generations[j].descriptor.CreatedAt)
	})
	retained := 0
	for _, generation := range generations {
		if err = ctx.Err(); err != nil {
			return err
		}
		if generation.valid && retained < keep {
			if verifyErr := verifyFactIndexGeneration(ctx, p, generation.descriptor); verifyErr == nil {
				retained++
				continue
			} else if errors.Is(verifyErr, errFactIndexUnsafe) {
				return verifyErr
			}
		}
		// Removing the descriptor first uncommits the database before unlink.
		if err = removeFactIndexLeaf(p, generation.digest+".json"); err != nil {
			return err
		}
		if err = removeFactIndexLeaf(p, generation.digest+".sqlite"); err != nil {
			return err
		}
	}
	return brainstore.SyncPinnedDirectory(p.scope)
}

