	"regexp"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/execx"
	"github.com/entireio/entire-brain/factmerge"
	"github.com/entireio/entire-brain/internal/cli/internal/factstore"
)

// TestFactIndexProcessBenchmark is a developer experiment, never an ordinary
// test-suite benchmark. Its serial child processes must run on an otherwise idle
// host. See docs/fact-index-benchmark.md for the retained evidence contract.
func TestFactIndexProcessBenchmark(t *testing.T) {
	t.Parallel()
	configPath := os.Getenv("ENTIRE_FACT_INDEX_BENCH_CONFIG")
	if configPath == "" {
		t.Skip("set ENTIRE_FACT_INDEX_BENCH_CONFIG to an explicit experiment config")
	}
	if runtime.GOOS != "darwin" && runtime.GOOS != "linux" {
		t.Skip("process peak RSS requires Darwin or Linux /usr/bin/time")
	}
	configData, err := os.ReadFile(configPath)
	if err != nil {
		t.Fatal(err)
	}
	var config factProcessConfig
	decoder := json.NewDecoder(bytes.NewReader(configData))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&config); err != nil {
		t.Fatal(err)
	}
	if err := config.validate(); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(config.OutputDir, 0o700); err != nil {
		t.Fatal(err)
	}
	entries, err := os.ReadDir(config.OutputDir)
	if err != nil || len(entries) != 0 {
		t.Fatalf("output_dir must be empty: entries=%d error=%v", len(entries), err)
	}
	metadata := map[string]any{"config": config, "go_version": runtime.Version(), "os": runtime.GOOS,
		"arch": runtime.GOARCH, "started_at": time.Now().UTC(), "rss_unit": "bytes",
		"wall_scope": "fresh CLI process plus /usr/bin/time wrapper; excludes fixture and inventory IO",
		"schedule": "serial rounds, rotate fixture and binary order; seven samples by default",
		"canonical_writer": "current test binary factstore.Write; unchanged writer, not per-binary CLI timing"}
	binaryHashes := make(map[string]string)
	for _, binary := range config.Binaries {
		binaryHashes[binary.Label], err = factProcessFileHash(binary.Path)
		if err != nil {
			t.Fatal(err)
		}
	}
	metadata["binary_sha256"] = binaryHashes
	factProcessWriteJSON(t, filepath.Join(config.OutputDir, "environment.json"), metadata)

	log, err := os.OpenFile(filepath.Join(config.OutputDir, "measurements.jsonl"), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
	if err != nil {
		t.Fatal(err)
	}
	defer log.Close()
	runner := factProcessRunner{t: t, config: config, log: json.NewEncoder(log), refs: make(map[string]string)}
	fixtures := make([]factProcessFixture, 0, len(config.Counts)+1)
	for _, count := range config.Counts {
		fixtures = append(fixtures, runner.fixture(fmt.Sprintf("synthetic-%d", count), factProcessSynthetic(count), config.Queries))
	}
	if config.PublicStore != "" {
		records, loadErr := factstore.Load(filepath.Dir(filepath.Dir(config.PublicStore)))
		if loadErr != nil || len(records) == 0 {
			t.Fatalf("load optional public corpus: count=%d error=%v", len(records), loadErr)
		}
		fixtures = append(fixtures, runner.fixture("public-import", records, config.PublicQueries))
	}

	// Cold means no application cache. It does not mean cold OS disk pages.
	// Clear only the disposable cache this harness just created, each time.
	for sample := 0; sample < config.Samples; sample++ {
		for offset := range fixtures {
			fixture := fixtures[(offset+sample)%len(fixtures)]
			for offset := range config.Binaries {
				bi := (offset+sample)%len(config.Binaries)
				cache := filepath.Join(fixture.Roots[bi], "cache")
				if err := os.RemoveAll(cache); err != nil {
					t.Fatal(err)
				}
				if err := os.Mkdir(cache, 0o700); err != nil {
					t.Fatal(err)
				}
				runner.query(fixture, bi, "first_build", sample, 0)
			}
		}
	}
	for sample := 0; sample < config.Samples; sample++ {
		for offset := range fixtures {
			fixture := fixtures[(offset+sample)%len(fixtures)]
			for qi := range fixture.Queries {
				for offset := range config.Binaries {
					runner.query(fixture, (offset+sample)%len(config.Binaries), "warm", sample, qi)
				}
			}
		}
	}
	if config.ExerciseRebuild {
		for _, fixture := range fixtures {
			for bi := range config.Binaries {
				brainDir := fixture.BrainDirs[bi]
				records, loadErr := factstore.Load(brainDir)
				if loadErr != nil {
					t.Fatal(loadErr)
				}
				// Measure a normal canonical replacement separately, outside query
				// timing. The final edit must be visible through the normal loader.
				for sample := 0; sample < config.Samples; sample++ {
					start := time.Now()
					writeErr := factstore.Write(brainDir, records)
					elapsed := time.Since(start)
					if writeErr != nil {
						t.Fatal(writeErr)
					}
					runner.record(factProcessMeasurement{Fixture: fixture.Name, Binary: config.Binaries[bi].Label,
						Phase: "canonical_write", Sample: sample, WallMS: float64(elapsed)/float64(time.Millisecond)})
				}
				records[0].Text += " enh004revisionmarker"
				if err := factstore.Write(brainDir, records); err != nil {
					t.Fatal(err)
				}
				runner.query(fixture, bi, "source_changed", 0, 0)
				changedFixture := fixture
				changedFixture.Queries = append(append([]string(nil), fixture.Queries...), "enh004revisionmarker")
				runner.query(changedFixture, bi, "changed_record_visible", 0, len(changedFixture.Queries)-1)
				if config.ExerciseCorruption {
					runner.corruptCache(fixture, bi)
					runner.query(fixture, bi, "corruption_recovery", 0, 0)
				}
			}
		}
	}
	factProcessWriteJSON(t, filepath.Join(config.OutputDir, "summary.json"), factProcessSummarize(runner.rows))
	t.Logf("retained %d measurements in %s", len(runner.rows), config.OutputDir)
}

