}

func insertFactIndexDocuments(ctx context.Context, tx *sql.Tx, source []factRecord, signatures []string) ([]factIndexDocument, error) {
	postings, err := tx.PrepareContext(ctx, factIndexPostingInsertSQL(factIndexPostingBatchRows))
	if err != nil {
		return nil, err
	}
	defer postings.Close()
	// Metadata is a bounded vector; SQL only indexes term postings.
	documents := make([]factIndexDocument, 0, len(source))
	pending := make([]any, 0, factIndexPostingBatchRows*3)
	pendingBytes := 0
	flush := func() error {
		if len(pending) == 0 {
			return nil
		}
		var flushErr error
		if len(pending) == factIndexPostingBatchRows*3 {
			_, flushErr = postings.ExecContext(ctx, pending...)
		} else {
			_, flushErr = tx.ExecContext(ctx, factIndexPostingInsertSQL(len(pending)/3), pending...)
		}
		clear(pending)
		pending = pending[:0]
		pendingBytes = 0
		return flushErr
	}
	for i := range source {
		if err = ctx.Err(); err != nil {
			return nil, err
		}
		tokens := factSearchTokens(source[i])
		documents = append(documents, factIndexDocument{Signature: signatures[i], Length: len(tokens), Locus: base.FactLocusOf(source[i])})
		counts := make(map[string]int, len(tokens))
		for _, token := range tokens {
			counts[token]++
		}
		for token, n := range counts {
			if pendingBytes > 0 && len(token) > factIndexPostingBatchBytes-pendingBytes {
				if err = flush(); err != nil {
					return nil, err
				}
			}
			pending = append(pending, token, i, n)
			pendingBytes += len(token)
			if len(pending) == factIndexPostingBatchRows*3 || pendingBytes >= factIndexPostingBatchBytes {
				if err = flush(); err != nil {
					return nil, err
				}
			}
		}
	}
	if err = flush(); err != nil {
		return nil, err
	}
	return documents, nil
}
