func factIndexRandomName(suffix string) (string, error) {
	var data [16]byte
	if _, err := rand.Read(data[:]); err != nil {
		return "", err
	}
	return factIndexPublishPrefix + hex.EncodeToString(data[:]) + suffix, nil
}

func createFactIndexPublicationLeaf(root *os.Root, suffix string) (*os.File, string, error) {
	name, err := factIndexRandomName(suffix)
	if err != nil {
		return nil, "", err
	}
	f, err := root.OpenFile(name, os.O_CREATE|os.O_EXCL|os.O_WRONLY|base.FileLockOpenFlags(), 0600)
	if err != nil {
		return nil, "", err
	}
	return f, name, nil
}

func publishFactIndexDatabase(ctx context.Context, p *factIndexPinnedDirectory, staging, digest string, count int) error {
	return publishFactIndexDatabaseWithBoundary(ctx, p, staging, digest, count, nil)
}

// The callback exposes the two multi-file commit boundaries without global
// mutable state. Normal callers use the wrapper above.
func publishFactIndexDatabaseWithBoundary(ctx context.Context, p *factIndexPinnedDirectory, staging, digest string, count int, boundary func(string) error) error {
	source, err := os.Open(staging)
	if err != nil {
		return err
	}
	defer source.Close()
	target, tempName, err := createFactIndexPublicationLeaf(p.scope, ".sqlite")
	if err != nil {
		return err
	}
	defer func() { _ = target.Close(); _ = p.scope.Remove(tempName) }()
	h := sha256.New()
	n, err := io.CopyBuffer(io.MultiWriter(target, h), io.LimitReader(&factIndexContextReader{ctx: ctx, reader: source}, factIndexMaxBytes+1), make([]byte, 64<<10))
	if err != nil {
		return err
	}
	if n < 1 || n > factIndexMaxBytes {
		return errFactIndexBudget
	}
	if err = target.Sync(); err != nil {
		return err
	}
	if err = target.Close(); err != nil {
		return err
	}
	if err = p.validate(); err != nil {
		return err
	}
	descriptor := factIndexDescriptor{Revision: currentFactIndexRevision(), Source: digest, Documents: count, Size: n, SHA256: hex.EncodeToString(h.Sum(nil)), CreatedAt: time.Now().UTC()}
	if !factIndexHexDigest(digest) || count < 0 || count > factIndexMaxDocuments {
		return errFactIndexUnsafe
	}
	// Verify an old committed generation before pruning to one. A failed new
	// publication then still retains a complete, byte-verified old generation.
	if err = retainFactIndexGenerations(ctx, p, digest, 1); err != nil {
		return err
	}
	// Different builds of the same source can have different SQLite bytes.
	// Publish a content-qualified blob so the old descriptor keeps its original
	// database until the replacement descriptor has been durably committed.
	if err = publishFactIndexBlob(ctx, p, tempName, descriptor); err != nil {
		return err
	}
	if err = brainstore.SyncPinnedDirectory(p.scope); err != nil {
		return err
	}
	if boundary != nil {
		if err = boundary("database_synced"); err != nil {
			return err
		}
	}
	data, err := json.Marshal(descriptor)
	if err != nil {
		return err
	}
	marker, markerName, err := createFactIndexPublicationLeaf(p.scope, ".json")
	if err != nil {
		return err
	}
	defer func() { _ = marker.Close(); _ = p.scope.Remove(markerName) }()
	if _, err = marker.Write(append(data, '\n')); err != nil {
		return err
	}
	if err = marker.Sync(); err != nil {
		return err
	}
	if err = marker.Close(); err != nil {
		return err
	}
	if err = ctx.Err(); err != nil {
		return err
	}
	if boundary != nil {
		if err = boundary("descriptor_ready"); err != nil {
			return err
		}
	}
	// The descriptor is the commit record and is always published last.
	if err = replaceFactIndexLeaf(p, markerName, digest+".json"); err != nil {
		return err
	}
	if err = brainstore.SyncPinnedDirectory(p.scope); err != nil {
		return err
	}
	// Only after the descriptor rename is durable may the previous same-source
	// blob be removed. Failed publications leave that referenced blob untouched.
	if err = cleanupFactIndexOrphans(ctx, p); err != nil {
		return err
	}
	return p.validate()
}

