func verifyFactIndexGeneration(ctx context.Context, p *factIndexPinnedDirectory, descriptor factIndexDescriptor) error {
	name := factIndexDatabaseName(descriptor)
	f, info, err := factIndexOpenLeaf(p.scope, name, factIndexMaxBytes)
	if err != nil {
