func factIndexRandomName(suffix string) (string, error) {
	var data [16]byte
	if _, err := rand.Read(data[:]); err != nil {
		return "", err
	}
	return factIndexPublishPrefix + hex.EncodeToString(data[:]) + suffix, nil
}

func createFactIndexPublicationLeaf(root *os.Root, suffix string) (*os.File, string, error) {
	name, err := factIndexRandomName(suffix)
	if err != nil {
		return nil, "", err
	}
	f, err := root.OpenFile(name, os.O_CREATE|os.O_EXCL|os.O_WRONLY|base.FileLockOpenFlags(), 0600)
	if err != nil {
		return nil, "", err
	}
	return f, name, nil
}

